describe('Multiple Concurrent API Calls Resolution', () => {
  beforeEach(() => {
    cy.visit('/dashboard');
  });

  it('should resolve multiple concurrent API calls before displaying data', () => {
    // Intercept the first API call
    cy.intercept('GET', '/api/user/profile').as('userProfile');
    // Intercept the second API call
    cy.intercept('GET', '/api/user/settings').as('userSettings');
    // Intercept the third API call
    cy.intercept('GET', '/api/user/notifications').as('userNotifications');

    // Click the button to trigger all three API calls concurrently
    cy.get('[data-testid="load-dashboard-btn"]').click();

    // Wait for all three API calls to complete
    cy.wait('@userProfile');
    cy.wait('@userSettings');
    cy.wait('@userNotifications');

    // Verify that the data is displayed after all calls resolve
    cy.get('[data-testid="profile-data"]').should('be.visible');
    cy.get('[data-testid="settings-data"]').should('contain', 'dark mode');
    cy.get('[data-testid="notifications-count"]').should('contain', '3');

    // Verify the loading indicator is no longer visible
    cy.get('[data-testid="loading-spinner"]').should('not.exist');
  });

  it('should handle API call failures and display error messages', () => {
    // Intercept the first API call successfully
    cy.intercept('GET', '/api/user/profile', {
      statusCode: 200,
      body: { id: 1, name: 'John Doe' }
    }).as('userProfile');

    // Intercept the second API call with a failure
    cy.intercept('GET', '/api/user/settings', {
      statusCode: 500,
      body: { error: 'Internal Server Error' }
    }).as('userSettingsFailed');

    // Intercept the third API call successfully
    cy.intercept('GET', '/api/user/notifications', {
      statusCode: 200,
      body: { count: 5 }
    }).as('userNotifications');

    // Click the button to trigger all three API calls
    cy.get('[data-testid="load-dashboard-btn"]').click();

    // Wait for all three API calls to complete
    cy.wait('@userProfile');
    cy.wait('@userSettingsFailed');
    cy.wait('@userNotifications');

    // Verify successful data is displayed
    cy.get('[data-testid="profile-data"]').should('be.visible');
    cy.get('[data-testid="notifications-count"]').should('contain', '5');

    // Verify error message is displayed for failed call
    cy.get('[data-testid="settings-error"]').should('be.visible');
    cy.get('[data-testid="settings-error"]').should('contain', 'Internal Server Error');

    // Verify loading indicator is gone
    cy.get('[data-testid="loading-spinner"]').should('not.exist');
  });
});
